/**
 * Per-input validation schema. Only these keys are accepted: type,
 * description, required, default, enum, minLength, maxLength, pattern,
 * format, minimum, maximum, exclusiveMinimum, exclusiveMaximum, and
 * multipleOf. Extra JSON Schema metadata is not supported.
 *
 */
export const zWorkflowInputSchema = z.object({
    type: zWorkflowInputType,
    description: z.optional(z.string().check(z.minLength(1))),
    required: z.boolean(),
    default: z.optional(zWorkflowInputScalarValue),
    enum: z.optional(z.array(zWorkflowInputScalarValue).check(z.minLength(1))),
    minLength: z.optional(z.int().check(z.gte(0))),
    maxLength: z.optional(z.int().check(z.gte(0))),
    pattern: z.optional(z.string().check(z.minLength(1))),
    format: z.optional(zWorkflowInputStringFormat),
    minimum: z.optional(z.number()),
    maximum: z.optional(z.number()),
    exclusiveMinimum: z.optional(z.number()),
    exclusiveMaximum: z.optional(z.number()),
    multipleOf: z.optional(z.number().check(z.gt(0)))
});

/**
 * Arbitrary JSON workflow input contract. Use this instead of typed workflow inputs when a workflow should accept one free-form JSON payload.
 *
 */
